function expand(stored) {
    const { capabilities, ...fields } = stored;
    const manifest = {
        ...structuredClone(fields),
        capabilities: capabilities.map((index) => {
            const [capability, state, refusal_point, diagnostic_code, requirements, vectors, summary] = ENTRIES[index];
            return { capability, state, summary, refusal_point, diagnostic_code, requirements: [...requirements], vectors: [...vectors] };
        }),
    };
    return manifest;
}
function predecessorsOf(profile) {
    return MANIFESTS.filter((stored) => stored.profile === profile).map(expand);
}
